export function pathMeasure(points){let lengths=[0];for(let i=1;i<points.length;i++)lengths.push(lengths.at(-1)+Math.hypot(points[i][0]-points[i-1][0],points[i][1]-points[i-1][1]));return{lengths,L:lengths.at(-1)}}
export function alongPath(points,d){const{lengths,L}=pathMeasure(points);d=Math.max(0,Math.min(L,d));let i=lengths.findIndex((v,k)=>k>0&&v>=d);if(i<1)i=points.length-1;let t=(d-lengths[i-1])/(lengths[i]-lengths[i-1]||1);return points[i-1].map((v,k)=>v+(points[i][k]-v)*t)}
export function projectPath(points,p){let best={distance:Infinity,d:0},passed=0;for(let i=1;i<points.length;i++){let a=points[i-1],b=points[i],dx=b[0]-a[0],dy=b[1]-a[1],L=Math.hypot(dx,dy),t=Math.max(0,Math.min(1,((p[0]-a[0])*dx+(p[1]-a[1])*dy)/(L*L||1))),distance=Math.hypot(p[0]-a[0]-dx*t,p[1]-a[1]-dy*t);if(distance<best.distance)best={distance,d:passed+t*L};passed+=L}return best}
export function sliceLoops(g,n,w,h,z){const edges=new Map(),tol=Math.max(w,h)*1e-8,key=p=>p.map(v=>Math.round(v/tol)).join(',');function edge(a,b){let ka=key(a),kb=key(b);if(ka===kb)return;const rev=kb+'|'+ka,id=ka+'|'+kb;if(edges.has(rev))edges.delete(rev);else edges.set(id,[a,b])}for(let j=0;j<n;j++)for(let i=0;i<n;i++){let k=j*(n+1)+i,ps=[[i*w/n,j*h/n,g[k]],[(i+1)*w/n,j*h/n,g[k+1]],[(i+1)*w/n,(j+1)*h/n,g[k+n+2]],[i*w/n,(j+1)*h/n,g[k+n+1]]];for(let ids of [[0,1,2],[0,2,3]]){let tri=ids.map(k=>ps[k]),poly=[];for(let a=0;a<3;a++){let p=tri[a],q=tri[(a+1)%3];if(p[2]>=z)poly.push(p.slice(0,2));if((p[2]>=z)!==(q[2]>=z)){let t=(z-p[2])/(q[2]-p[2]);poly.push([p[0]+t*(q[0]-p[0]),p[1]+t*(q[1]-p[1])])}}for(let a=0;a<poly.length;a++)edge(poly[a],poly[(a+1)%poly.length])}}
const starts=new Map();for(let [id,e] of edges){let k=key(e[0]);if(!starts.has(k))starts.set(k,[]);starts.get(k).push(id)}let loops=[];while(edges.size){let [id,first]=edges.entries().next().value,start=key(first[0]),loop=[],closed=false;while(id&&edges.has(id)){let e=edges.get(id);edges.delete(id);loop.push(e[0]);let next=key(e[1]);if(next===start){closed=true;break}id=(starts.get(next)||[]).find(k=>edges.has(k))}if(!closed)throw Error('切片邊界未閉合，請微調切片基準高程');if(loop.length>=3){let area=loop.reduce((s,p,i)=>{let q=loop[(i+1)%loop.length];return s+p[0]*q[1]-q[0]*p[1]},0)/2;if(Math.abs(area)>tol*tol)loops.push(loop)}}return loops}
export function makeSlices(g,n,w,h,ratio,thickness,base){if(!(ratio>0&&thickness>0&&Number.isFinite(base)))throw Error('比例、板厚或基準無效');let max=Math.max(...g),step=ratio*thickness/1000,count=Math.ceil((max-base)/step);if(count<1)throw Error('基準高程必須低於最高地形');if(count>200)throw Error('切片超過 200 層，請增加板厚或縮小模型比例');let slices=[];for(let i=0;i<count;i++){let z=base+i*step,loops=sliceLoops(g,n,w,h,z+step*1e-7).map(loop=>loop.map(p=>p.map(v=>v*1000/ratio)));if(!loops.length)continue;let pts=loops.flat(),xs=pts.map(p=>p[0]),ys=pts.map(p=>p[1]),x=Math.min(...xs),y=Math.min(...ys);slices.push({id:i+1,z,loops:loops.map(l=>l.map(p=>[p[0]-x,p[1]-y])),offset:[x,y],w:Math.max(...xs)-x,h:Math.max(...ys)-y})}return slices}
// Shelf packing with optional 90-degree rotation; preserves every island/hole in each elevation group.
export function nest(slices,W,H,gap,margin,rotate=true){if(!(W>0&&H>0&&gap>=0&&margin>=0&&2*margin<Math.min(W,H)))throw Error('板材尺寸、間距或邊距無效');let boards=[];for(let s of [...slices].sort((a,b)=>Math.max(b.w,b.h)-Math.max(a.w,a.h))){let choices=[{w:s.w,h:s.h,rot:false}];if(rotate)choices.push({w:s.h,h:s.w,rot:true});choices=choices.filter(c=>c.w<=W-2*margin+1e-7&&c.h<=H-2*margin+1e-7);if(!choices.length)throw Error('第 '+s.id+' 層超過板材可用尺寸，請縮小模型或加大板材');let placed=false;for(let b of boards){for(let row of b.rows){let c=choices.filter(c=>c.h<=row.h+1e-7&&row.x+c.w<=W-margin+1e-7).sort((a,b)=>a.w-b.w)[0];if(c){b.items.push({...s,...c,x:row.x,y:row.y});row.x+=c.w+gap;placed=true;break}}if(placed)break;let y=b.rows.length?b.rows.at(-1).y+b.rows.at(-1).h+gap:margin,c=choices.filter(c=>y+c.h<=H-margin+1e-7).sort((a,b)=>a.h-b.h)[0];if(c){b.rows.push({y,h:c.h,x:margin+c.w+gap});b.items.push({...s,...c,x:margin,y});placed=true;break}}if(!placed){let c=choices.sort((a,b)=>a.h-b.h)[0];boards.push({rows:[{y:margin,h:c.h,x:margin+c.w+gap}],items:[{...s,...c,x:margin,y:margin}]})}}return boards}
export function placedLoops(item){return item.loops.map(l=>l.map(([x,y])=>item.rot?[item.x+y,item.y+x]:[item.x+x,item.y+item.h-y]))}
export function svgBoard(board,W,H,labels=false){const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;');return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}mm" height="${H}mm" viewBox="0 0 ${W} ${H}"><title>Terrain laser cutting; millimetres; CUT paths, optional ENGRAVE labels</title><g id="CUT" fill="none" stroke="#ff0000" stroke-width="0.01">`+board.items.map(i=>`<path id="layer-${i.id}" data-elevation="${i.z}" d="${placedLoops(i).map(l=>'M'+l.map(p=>p.map(v=>v.toFixed(4)).join(',')).join('L')+'Z').join(' ')}"/>`).join('')+'</g>'+(labels?'<g id="ENGRAVE" font-family="sans-serif" font-size="2.5" fill="#0000ff">'+board.items.map(i=>`<text x="${i.x+2}" y="${i.y+4}">${esc('L'+i.id+' / '+i.z.toFixed(2)+'m')}</text>`).join('')+'</g>':'')+'</svg>'}
export function dxfBoard(board,W,H,labels=false){let out=['0','SECTION','2','HEADER','9','$ACADVER','1','AC1015','9','$INSUNITS','70','4','0','ENDSEC','0','SECTION','2','ENTITIES'];for(let item of board.items){for(let l of placedLoops(item)){out.push('0','LWPOLYLINE','100','AcDbEntity','8','CUT','62','1','100','AcDbPolyline','90',String(l.length),'70','1');for(let p of l)out.push('10',p[0].toFixed(5),'20',(H-p[1]).toFixed(5))}if(labels)out.push('0','TEXT','100','AcDbEntity','8','ENGRAVE','62','5','100','AcDbText','10',String(item.x+2),'20',String(H-item.y-4),'40','2.5','1','L'+item.id+' / '+item.z.toFixed(2)+'m')}out.push('0','ENDSEC','0','EOF');return out.join('\n')+'\n'}
export function solidTerrain(g,n,w,h){const floor=Math.min(...g)-Math.max(w,h)*.045,vertices=[],faces=[],count=(n+1)**2;for(let base of [false,true])for(let j=0;j<=n;j++)for(let i=0;i<=n;i++)vertices.push([i*w/n,j*h/n,base?floor:g[j*(n+1)+i]]);for(let j=0;j<n;j++)for(let i=0;i<n;i++){let k=j*(n+1)+i;faces.push([k,k+1,k+n+2],[k,k+n+2,k+n+1],[count+k,count+k+n+2,count+k+1],[count+k,count+k+n+1,count+k+n+2])}let edge=[];for(let i=0;i<n;i++)edge.push(i);for(let j=0;j<n;j++)edge.push(j*(n+1)+n);for(let i=n;i>0;i--)edge.push(n*(n+1)+i);for(let j=n;j>0;j--)edge.push(j*(n+1));for(let i=0;i<edge.length;i++){let a=edge[i],b=edge[(i+1)%edge.length];faces.push([a,count+a,count+b],[a,count+b,b])}return{vertices,faces,floor}}
